use crate::{expr::{Expr, Intrinsic}, operators::expression_type, types::TypeInfo, value::Value};
use super::{MlirBuilder, Ref, RefKind};

impl<'a> MlirBuilder<'a> {
    fn expr_type(&self,e:&Expr)->Result<TypeInfo,String>{let types=self.refs.iter().map(|r|r.ty.clone()).collect::<Vec<_>>();expression_type(&types,e)}
    pub(crate) fn lower_expr(&mut self,e:&Expr,expected:&TypeInfo)->Result<Ref,String>{match e{Expr::Argument(i)=>{let idx=self.closure.captures.len()+*i;self.refs.get(idx).cloned().ok_or_else(||format!("argument index {} out of bounds",i)).map(|r|if r.kind==RefKind::Address{Ref{name:self.load(&r.name,&r.ty),ty:r.ty,kind:RefKind::Value}}else{r})},Expr::Capture(i)=>self.refs.get(*i).cloned().ok_or_else(||format!("capture index {} out of bounds",i)),Expr::Constant(v)=>self.constant(v),Expr::Cast{expr,source_type,target_type}=>{let a=self.lower_ref(expr,source_type)?;self.cast(a,target_type)},Expr::Index{sequence,index}=>{let a=self.index_address(sequence,index)?;Ok(Ref{name:self.load(&a.name,&a.ty),ty:a.ty,kind:RefKind::Value})},Expr::Len{sequence}=>{let a=self.address_of_expr(sequence)?;match a.ty{TypeInfo::Array{length,..}=>Ok(Ref{name:self.c_i64(length as i64),ty:TypeInfo::Usize,kind:RefKind::Value}),TypeInfo::Slice{..}=>{let p=self.gep_const(&a.name,&a.ty,&[0,1]);Ok(Ref{name:self.load(&p,&TypeInfo::Usize),ty:TypeInfo::Usize,kind:RefKind::Value})},_=>Err("len() requires a sequence".into())}},Expr::Field{object,name}=>{let a=self.address_of_expr(object)?;let fields=match &a.ty{TypeInfo::Struct{fields,..}=>fields,_=>return Err("field access requires struct".into())};let(i,f)=fields.iter().enumerate().find(|(_,f)|f.name==*name).ok_or_else(||format!("field `{}` not found",name))?;let p=self.gep_const(&a.name,&a.ty,&[0,i]);Ok(Ref{name:self.load(&p,&f.type_info),ty:f.type_info.clone(),kind:RefKind::Value})},Expr::Struct{type_info,fields}=>self.aggregate(type_info,fields),Expr::Tuple{elements}=>{let ty=self.expr_type(e)?;let fields=elements.iter().enumerate().map(|(i,e)|(i.to_string(),e.clone())).collect::<Vec<_>>();self.aggregate(&ty,&fields)},Expr::Intrinsic{intrinsic,arguments}=>self.intrinsic(*intrinsic,arguments),Expr::IfElse{condition,then_branch,else_branch}=>self.if_expr(condition,then_branch,else_branch,expected),Expr::Add{lhs,rhs}=>self.binary("add",lhs,rhs,expected),Expr::Sub{lhs,rhs}=>self.binary("sub",lhs,rhs,expected),Expr::Mul{lhs,rhs}=>self.binary("mul",lhs,rhs,expected),Expr::Div{lhs,rhs}=>self.binary("div",lhs,rhs,expected),Expr::Rem{lhs,rhs}=>self.binary("rem",lhs,rhs,expected),Expr::Eq{lhs,rhs}=>self.compare("eq",lhs,rhs),Expr::Ne{lhs,rhs}=>self.compare("ne",lhs,rhs),Expr::Lt{lhs,rhs}=>self.compare("lt",lhs,rhs),Expr::Le{lhs,rhs}=>self.compare("le",lhs,rhs),Expr::Gt{lhs,rhs}=>self.compare("gt",lhs,rhs),Expr::Ge{lhs,rhs}=>self.compare("ge",lhs,rhs),Expr::And{lhs,rhs}=>self.logical("and",lhs,rhs),Expr::Or{lhs,rhs}=>self.logical("or",lhs,rhs),Expr::BitAnd{lhs,rhs}=>self.binary("and",lhs,rhs,expected),Expr::BitOr{lhs,rhs}=>self.binary("or",lhs,rhs,expected),Expr::BitXor{lhs,rhs}=>self.binary("xor",lhs,rhs,expected),Expr::Shl{lhs,rhs}=>self.binary("shl",lhs,rhs,expected),Expr::Shr{lhs,rhs}=>self.binary(if expected.is_signed_integer(){"ashr"}else{"lshr"},lhs,rhs,expected),Expr::Not{operand}=>{let a=self.lower_expr(operand,&TypeInfo::Bool)?;let one=self.c_bool(true);let n=self.value();self.text.push_str(&format!("    {} = llvm.xor {}, {} : i1\n",n,a.name,one));Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})},Expr::Neg{operand}=>{let a=self.lower_expr(operand,expected)?;let n=self.value();if expected.is_float(){self.text.push_str(&format!("    {} = llvm.fneg {} : {}\n",n,a.name,Self::ty(expected)))}else{let z=self.c_int("0",&Self::ty(expected));self.text.push_str(&format!("    {} = llvm.sub {}, {} : {}\n",n,z,a.name,Self::ty(expected)))}Ok(Ref{name:n,ty:expected.clone(),kind:RefKind::Value})}}}
    pub(crate) fn aggregate(&mut self,ty:&TypeInfo,fields:&[(String,Expr)])->Result<Ref,String>{let mut r=self.value();self.text.push_str(&format!("    {} = llvm.mlir.undef : {}\n",r,Self::ty(ty)));match ty{TypeInfo::Struct{fields:expected,..}=>{for(i,(name,e))in fields.iter().enumerate(){let f=expected.iter().find(|f|f.name==*name).ok_or("invalid struct field")?;let a=self.lower_expr(e,&f.type_info)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.insertvalue {}, {}[{}] : {}\n",n,a.name,r,i,Self::ty(ty)));r=n;}},TypeInfo::Array{element,..}=>{for(i,(_,e))in fields.iter().enumerate(){let a=self.lower_expr(e,element)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.insertvalue {}, {}[{}] : {}\n",n,a.name,r,i,Self::ty(ty)));r=n;}},_=>return Err("invalid aggregate type".into())}Ok(Ref{name:r,ty:ty.clone(),kind:RefKind::Value})}
    pub(crate) fn constant(&mut self,v:&Value)->Result<Ref,String>{match v{Value::F32(x)=>Ok(Ref{name:self.c_float(&x.to_string(),"f32"),ty:TypeInfo::F32,kind:RefKind::Value}),Value::F64(x)=>Ok(Ref{name:self.c_float(&x.to_string(),"f64"),ty:TypeInfo::F64,kind:RefKind::Value}),Value::Bool(x)=>Ok(Ref{name:self.c_bool(*x),ty:TypeInfo::Bool,kind:RefKind::Value}),Value::I8(x)=>self.int_const(*x as i128,"i8",TypeInfo::I8),Value::I16(x)=>self.int_const(*x as i128,"i16",TypeInfo::I16),Value::I32(x)=>self.int_const(*x as i128,"i32",TypeInfo::I32),Value::I64(x)=>self.int_const(*x as i128,"i64",TypeInfo::I64),Value::I128(x)=>self.int_const(*x as i128,"i128",TypeInfo::I128),Value::U8(x)=>self.int_const(*x as i128,"i8",TypeInfo::U8),Value::U16(x)=>self.int_const(*x as i128,"i16",TypeInfo::U16),Value::U32(x)=>self.int_const(*x as i128,"i32",TypeInfo::U32),Value::U64(x)=>self.int_const(*x as i128,"i64",TypeInfo::U64),Value::U128(x)=>self.int_const(*x as i128,"i128",TypeInfo::U128),Value::Usize(x)=>self.int_const(*x as i128,"i64",TypeInfo::Usize),Value::Array(v)=>{let first=v.first().ok_or("empty array constants are not supported")?.clone();let et=self.expr_type(&Expr::Constant(first))?;let ty=TypeInfo::Array{element:Box::new(et),length:v.len()};let fields=v.iter().enumerate().map(|(i,x)|(i.to_string(),Expr::Constant(x.clone()))).collect::<Vec<_>>();self.aggregate(&ty,&fields)}}}
    pub(crate) fn int_const(&mut self,x:i128,ty:&str,ti:TypeInfo)->Result<Ref,String>{Ok(Ref{name:self.c_int(&x.to_string(),ty),ty:ti,kind:RefKind::Value})}
    pub(crate) fn binary(&mut self,op:&str,lhs:&Expr,rhs:&Expr,ty:&TypeInfo)->Result<Ref,String>{let a=self.lower_expr(lhs,ty)?;let b=self.lower_expr(rhs,ty)?;let n=self.value();let inst=if ty.is_float(){match op{"add"=>"fadd","sub"=>"fsub","mul"=>"fmul","div"=>"fdiv","rem"=>"frem",_=>return Err("invalid floating binary op".into())}}else{match op{"div"=>if ty.is_unsigned_integer(){"udiv"}else{"sdiv"},"rem"=>if ty.is_unsigned_integer(){"urem"}else{"srem"},x=>x}};self.text.push_str(&format!("    {} = llvm.{} {}, {} : {}\n",n,inst,a.name,b.name,Self::ty(ty)));Ok(Ref{name:n,ty:ty.clone(),kind:RefKind::Value})}
    pub(crate) fn compare(&mut self,op:&str,lhs:&Expr,rhs:&Expr)->Result<Ref,String>{let t=self.expr_type(lhs)?;let a=self.lower_expr(lhs,&t)?;let b=self.lower_expr(rhs,&t)?;let n=self.value();if t.is_float(){let p=match op{"eq"=>"oeq","ne"=>"one","lt"=>"olt","le"=>"ole","gt"=>"ogt","ge"=>"oge",_=>return Err("bad comparison".into())};self.text.push_str(&format!("    {} = llvm.fcmp \"{}\" {}, {} : {}\n",n,p,a.name,b.name,Self::ty(&t)))}else{let p=match op{"eq"=>"eq","ne"=>"ne","lt"=>if t.is_unsigned_integer(){"ult"}else{"slt"},"le"=>if t.is_unsigned_integer(){"ule"}else{"sle"},"gt"=>if t.is_unsigned_integer(){"ugt"}else{"sgt"},"ge"=>if t.is_unsigned_integer(){"uge"}else{"sge"},_=>return Err("bad comparison".into())};self.text.push_str(&format!("    {} = llvm.icmp \"{}\" {}, {} : {}\n",n,p,a.name,b.name,Self::ty(&t)))}Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})}
    pub(crate) fn logical(&mut self,op:&str,lhs:&Expr,rhs:&Expr)->Result<Ref,String>{let a=self.lower_expr(lhs,&TypeInfo::Bool)?;let b=self.lower_expr(rhs,&TypeInfo::Bool)?;let n=self.value();self.text.push_str(&format!("    {} = llvm.{} {}, {} : i1\n",n,op,a.name,b.name));Ok(Ref{name:n,ty:TypeInfo::Bool,kind:RefKind::Value})}
    pub(crate) fn cast(&mut self,a:Ref,target:&TypeInfo)->Result<Ref,String>{let s=Self::ty(&a.ty);let t=Self::ty(target);if a.ty==*target||(!a.ty.is_float()&&!target.is_float()&&Self::bits(&a.ty)==Self::bits(target)){return Ok(Ref{name:a.name,ty:target.clone(),kind:RefKind::Value})}let n=self.value();let op=if a.ty.is_float()&&target.is_float(){if Self::bits(target)<Self::bits(&a.ty){"fptrunc"}else{"fpext"}}else if a.ty.is_float(){if target.is_unsigned_integer(){"fptoui"}else{"fptosi"}}else if target.is_float(){if a.ty.is_unsigned_integer(){"uitofp"}else{"sitofp"}}else if Self::bits(target)<Self::bits(&a.ty){"trunc"}else if a.ty.is_unsigned_integer(){"zext"}else{"sext"};self.text.push_str(&format!("    {} = llvm.{} {} : {} to {}\n",n,op,a.name,s,t));Ok(Ref{name:n,ty:target.clone(),kind:RefKind::Value})}
    pub(crate) fn bits(t:&TypeInfo)->u32{match t{TypeInfo::I8|TypeInfo::U8=>8,TypeInfo::I16|TypeInfo::U16=>16,TypeInfo::I32|TypeInfo::U32=>32,TypeInfo::I64|TypeInfo::U64|TypeInfo::Usize=>64,TypeInfo::I128|TypeInfo::U128=>128,TypeInfo::Bool=>1,TypeInfo::F32=>32,TypeInfo::F64=>64,_=>0}}
    pub(crate) fn intrinsic(&mut self,i:Intrinsic,args:&[Expr])->Result<Ref,String>{let t=self.expr_type(&args[0])?;let a=self.lower_expr(&args[0],&t)?;let n=self.value();match i{Intrinsic::Sqrt|Intrinsic::Abs|Intrinsic::Floor|Intrinsic::Ceil|Intrinsic::Round|Intrinsic::Sin|Intrinsic::Cos|Intrinsic::Tan|Intrinsic::Exp|Intrinsic::Log=>{let op=match i{Intrinsic::Sqrt=>"sqrt",Intrinsic::Abs=>"fabs",Intrinsic::Floor=>"floor",Intrinsic::Ceil=>"ceil",Intrinsic::Round=>"round",Intrinsic::Sin=>"sin",Intrinsic::Cos=>"cos",Intrinsic::Tan=>"tan",Intrinsic::Exp=>"exp",Intrinsic::Log=>"log",_=>unreachable!()};self.text.push_str(&format!("    {} = llvm.intr.{}({}) : ({}) -> {}\n",n,op,a.name,Self::ty(&t),Self::ty(&t)));},Intrinsic::Min|Intrinsic::Max=>{let b=self.lower_expr(&args[1],&t)?;let op=if matches!(i,Intrinsic::Min){"minnum"}else{"maxnum"};self.text.push_str(&format!("    {} = llvm.intr.{}({}, {}) : ({}, {}) -> {}\n",n,op,a.name,b.name,Self::ty(&t),Self::ty(&t),Self::ty(&t)));},Intrinsic::Pow=>{let b=self.lower_expr(&args[1],&t)?;self.text.push_str(&format!("    {} = llvm.intr.pow({}, {}) : ({}, {}) -> {}\n",n,a.name,b.name,Self::ty(&t),Self::ty(&t),Self::ty(&t)));}}Ok(Ref{name:n,ty:t,kind:RefKind::Value})}
    pub(crate) fn if_expr(&mut self,c:&Expr,t:&Expr,e:&Expr,ty:&TypeInfo)->Result<Ref,String>{let cond=self.lower_expr(c,&TypeInfo::Bool)?;let temp=self.alloca(ty);let tb=self.block("if_then");let eb=self.block("if_else");let mb=self.block("if_merge");self.emit_cond(&cond.name,&tb,&eb);self.label(&tb);let tv=self.lower_expr(t,ty)?;self.store(&tv.name,&temp,ty);if !self.current_terminated{self.emit_branch(&mb)}self.label(&eb);let ev=self.lower_expr(e,ty)?;self.store(&ev.name,&temp,ty);if !self.current_terminated{self.emit_branch(&mb)}self.label(&mb);Ok(Ref{name:self.load(&temp,ty),ty:ty.clone(),kind:RefKind::Value})}
}